const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const weekStr = `${weekAgo.getFullYear()}年${weekAgo.getMonth()+1}月${weekAgo.getDate()}日～${now.getFullYear()}年${now.getMonth()+1}月${now.getDate()}日`;
const trendQueries = [
  { query: '最新 AI ツール 2026', label: '新AIツール' },
  { query: 'ChatGPT Claude Gemini 最新 機能 アップデート', label: 'LLM最新情報' },
  { query: 'AI 業務効率化 活用事例 日本', label: '国内AI活用事例' },
  { query: 'プロンプトエンジニアリング テクニック 最新', label: 'プロンプト技術' },
  { query: 'AI 自動化 n8n Make Zapier ワークフロー', label: 'AI自動化' }
];
return trendQueries.map(q => ({ json: { query: q.query, label: q.label, weekStr } }));

const items = $input.all();
const queryData = $('トレンドキーワード設定').all();
const sections = items.map((item, index) => ({ label: queryData[index]?.json.label || '', content: item.json.choices?.[0]?.message?.content || '' }));
const weekStr = queryData[0]?.json.weekStr || '';
return [{ json: { weekStr, sections } }];

const GITHUB_TOKEN = $env.GITHUB_TOKEN || '';
const PROMPT_FILE = '06-weekly-report.md';
const promptUrl = `https://api.github.com/repos/liquitex-coder/ai-solution-/contents/n8n/prompts/${PROMPT_FILE}`;
const headers = { 'Accept': 'application/vnd.github.v3+json', 'User-Agent': 'n8n-ai-navi/1.0' };
if (GITHUB_TOKEN) headers['Authorization'] = `token ${GITHUB_TOKEN}`;
let promptContent = '';
try {
  const res = await fetch(promptUrl, { headers });
  if (res.ok) {
    const data = await res.json();
    promptContent = Buffer.from((data.content || '').replace(/\n/g, ''), 'base64').toString('utf8');
  }
} catch (e) { promptContent = '<!-- prompt fetch failed -->'; }
return [{ json: { ...$json, promptContent } }];

const content = $json.content[0].text;
const weekStr = $('トレンドデータ集約').first().json.weekStr;
const now = new Date();
const monthDay = `${now.getMonth()+1}月${now.getDate()}日`;
return [{ json: { title: `【週次AIトレンド】${monthDay}週 - 注目のAIニュース・ツールまとめ`, content, status: 'publish' } }];
